import math

def calculate_r(n):
    if n <= 2:
        return "Invalid n (triangle sides must be positive)"

    # Calculate semi-perimeter s
    s = 3 * n / 2

    # Calculate area A using Heron's formula
    try:
        # s-a = (n+2)/2
        # s-b = n/2
        # s-c = (n-2)/2
        A_squared = s * ((n + 2) / 2) * (n / 2) * ((n - 2) / 2)
        A = math.sqrt(A_squared)

        # Calculate inradius r
        r = A / s
        return r
    except ValueError:
        return "Calculation Error"

# Test values starting from n=4
n_values = [4, 5, 6, 7]
results = {}
for n in n_values:
    r = calculate_r(n)
    results[n] = r

print(f"Results for n={n_values}:")
for n, r in results.items():
    if isinstance(r, float):
        print(f"n={n}, s={3*n/2}, r={r}")
    else:
        print(f"n={n}, {r}")
